; ======================================================================
; $8000  chunk copier. The file loads each 2.5 KB chunk at $4000 and then
; runs CopyChunk as INIT: with the OS ROM switched off it copies the chunk
; to the RAM under the ROM. $90 counts the chunks (0 at power-on).
; This segment is overwritten later by the $5BE8-$84E7 segment.
; ======================================================================
	opt h-			; segment headers are written out below,
				; to keep the original $FFFF before each one
	dta a($FFFF),a(cc_dst),a(cc_end_of_code-1)
	org $8000
cc_dst	dta $D8,$E2,$EC,$F6,$C0,$C9	; destination page of each chunk
cc_end	dta $4A,$54,$5E,$68,$49,$4F	; source page where it ends
cc_src	dta $40,$4A,$54,$5E,$40,$49	; source page
CopyChunk
	ldx $90
	lda cc_dst,x
	sta $83
	lda cc_end,x
	sta cc_cmp+1
	lda cc_src,x
	sta $81
	lda #$00
	sta $80
	sta $82
	sei
	lda #$00
	sta DMACTL
	sta NMIEN
	lda #$FE			; OS ROM off
	sta PORTB
	ldy #$00
cc_loop	lda ($80),y
	sta ($82),y
	inc $80
	bne cc_1
	inc $81
cc_1	inc $82
	bne cc_2
	inc $83
cc_2	lda $81
cc_cmp	cmp #$00			; patched: end page
	bne cc_loop
	inc $90
	lda #$FF			; OS ROM back on
	sta PORTB
	lda #$40
	sta NMIEN
	lda #$22
	sta DMACTL
	cli
	rts
cc_end_of_code

; chunk 1: $4000-$49FF, copied under the OS ROM to $D800-$E1FF
	dta a($FFFF),a($4000),a($49FF)
	ins 'data/rom_d800.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; chunk 2: $4A00-$53FF, copied under the OS ROM to $E200-$EBFF
	dta a($FFFF),a($4A00),a($53FF)
	ins 'data/rom_e200.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; chunk 3: $5400-$5DFF, copied under the OS ROM to $EC00-$F5FF
	dta a($FFFF),a($5400),a($5DFF)
	ins 'data/rom_ec00.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; chunk 4: $5E00-$67FF, copied under the OS ROM to $F600-$FFFF
	dta a($FFFF),a($5E00),a($67FF)
	ins 'data/rom_f600.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; chunk 5: $4000-$48FF, copied under the OS ROM to $C000-$C8FF
	dta a($FFFF),a($4000),a($48FF)
	ins 'data/rom_c000.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; chunk 6: $4900-$4EFF, copied under the OS ROM to $C900-$CEFF
	dta a($FFFF),a($4900),a($4EFF)
	ins 'data/rom_c900.bin'
	dta a(INITAD),a(INITAD+1),a(CopyChunk)

; ======================================================================
; $0480-$3D7F  the program. Loaded at $1480; the RUN stub moves it here.
; ======================================================================
	dta a($FFFF),a(Start+$1000),a(main_end+$1000-1)
	org $0480
