; ColdStart: set up the machine, then show the title screen.
; RESET comes back to Reset through CASINI (BOOT=2).
ColdStart	nop
        	nop
        	nop
Reset           lda PORTB               ; BASIC off
        	ora #$02
        	sta PORTB
        	lda #$02
        	sta BOOT
