; CopyBlocks: copy t0 blocks of 128 bytes from cp_src to cp_dst
; with the OS ROM switched off (the data lives under the ROM).
CopyBlocks	sei
        	lda DMACTL
        	pha
        	lda NMIEN
        	pha
        	lda PORTB
        	pha
        	lda #$00
        	sta DMACTL
        	sta NMIEN
        	lda #$FE
        	sta PORTB
L34D5   	jsr Copy128
        	dec t0
        	bne L34D5
        	pla
        	sta PORTB
        	pla
        	sta NMIEN
        	pla
        	sta DMACTL
        	cli
        	rts

Copy128 	lda #$80
        	sta cp_n
        	ldy #$00
L34F0   	lda (cp_src),y
        	sta (cp_dst),y
        	inc cp_src
        	bne L34FA
        	inc cp_src+1
L34FA   	inc cp_dst
        	bne L3500
        	inc cp_dst+1
L3500   	dec cp_n
        	bne L34F0
        	rts

